 "content": "def transform(grid):
    # Build the output from the four connected components. Components are
    # grouped by color, the smaller motif is placed above the larger motif.
    h, w = len(grid), len(grid[0])
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if not color or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    py,px=p
                    if 0<=py<h and 0<=px<w and p not in seen and grid[py][px]==color:
                        seen.add(p); stack.append(p)
            objects.append((color,cells))
    out=[[0]*w for _ in range(h)]
    colors=sorted({color for color,_ in objects})
    for ci,color in enumerate(colors):
        lane=0 if ci==0 else 5
        group=[cells for col,cells in objects if col==color]
        group.sort(key=len)
        if color==min(colors):
            # small upper motif; large lower motif
            tops=[4,7]
        else:
            # large lower-origin motif above, smaller top-origin motif below
            tops=[5,9]
            group.reverse()
        for cells,top in zip(group,tops):
            r0=min(r for r,c in cells); c0=min(c for r,c in cells)
            for r,c in cells:
                out[top+r-r0][lane+c-c0]=color
    return out
